static const size_t font_count = sizeof(font_table) / sizeof(font_table[0]);

static const uint16_t *font_get_bycode(const uint16_t code) {
    if(code == 0)return NULL;
    //二分探索開始
    size_t low = 0; //探索範囲の先頭側
    size_t high = font_count; //探索範囲の末尾の次
    while(low < high){
        size_t mid = low + (high - low)/2;
        if(font_table[mid].code == code) {
            return font_table[mid].data;
        }else if(font_table[mid].code < code) low = mid + 1;
        else high = mid;
    }
    return NULL;
}

//指定ピクセルは０か１かを出力
static bool pixelset_12px_DenkiChip(const void *data, size_t x, size_t y, size_t offset){
    const uint16_t *rows = data;
    if(x >= 12 || y >= 12) return false;
    return (rows[y] & (0x800 >> (x + offset))) != 0;
}

//構造体FontGlyphに該当コードポイントのドットデータと情報を代入
bool get_glyph_12px_DenkiChip(uint16_t codepoint, FontGlyph *out){
    if(out == NULL) {
        return false;
    }

    const uint16_t *rows = font_get_bycode(codepoint);
    if(rows == NULL) {
        return false;
    }
    if((0x0020 <= codepoint && codepoint <= 0x007E) //ASCII文字(半角英数記号)
        ||(0xff61 <= codepoint && codepoint <= 0xff9f)) //半角カタカナ
        {
            out->width = Font_12px_Denkichip_info.width_halffont;
        }else if( (0x3040 <= codepoint && codepoint <= 0x309F) //ひらがな
        ||(0x30A0 <= codepoint && codepoint <= 0x30FF)) //カタカナ
        {
            out->width = Font_12px_Denkichip_info.width_kanafont;
        } else {
            out->width = Font_12px_Denkichip_info.width; //それ以外は全角
        }
    out->height = Font_12px_Denkichip_info.height;
    out->data = rows;
    out->pixelset = pixelset_12px_DenkiChip;
    
    return true;
}